/ Crea un nuevo AreasComune.        /// </summary>        /// <param name="objInput">Datos para crear el AreasComune.</param>        /// <param name="userId">ID de usuario (cabecera “UserID”).</param>        /// <param name="windowName">Nombre de aplicación (cabecera “WindowName”).</param>        Task<clReadAreasComunes> CreateAreasComunes(            clCreateAreasComunes objInput,            int userId,            string windowName);        /// <summary>        /// Actualiza campos selectivos de un AreasComune.        /// </summary>        /// <param name="objInput">Datos para actualizar el AreasComune, incluyendo su ID y campos a modificar.</param>        /// <param name="userId">ID de usuario (cabecera “UserID”).</param>        /// <param name="windowName">Nombre de aplicación (cabecera “WindowName”).</param>        Task<clReadAreasComunes?> UpdateAreasComunes(            clUpdateAreasComunes objInput,            int userId,            string windowName);        /// <summary>        /// Elimina un AreasComune por su ID.        /// </summary>        /// <param name="nAreasComunesID">ID del AreasComune a eliminar.</param>        Task<bool> DeleteAreasComunes(int nAreasComunesID);    }}